from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import refund_shipping
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def p(amt="100.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status="captured",created_at=T0,captured_at=T0)

# partial then full
x=p(); refund_shipping(x,Decimal("40.00"),T0); assert x.refunded_amount==Decimal("40.00") and x.status=="captured"
refund_shipping(x,Decimal("60.00"),T0); assert x.refunded_amount==Decimal("100.00") and x.status=="refunded"
