# over refund
x=p()
try: refund_shipping(x,Decimal("100.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for a in ("0","-1"):
    try: refund_shipping(p(),Decimal(a),T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# approval
x=p("1000.00")
try: refund_shipping(x,Decimal("500.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
refund_shipping(x,Decimal("500.00"),T0); print("at threshold ok")
